import{_ as s,o as a,c as i,j as e}from"./chunks/framework.8tqBsFWt.js";const m=JSON.parse(`{"title":"The Dashboard Is Always Current","description":"The client's reporting view and the database are separate spreadsheets. The client can never accidentally break the data — and they never have to request a report.","frontmatter":{"title":"The Dashboard Is Always Current","date":"2026-03-13","series":"Architecture","description":"The client's reporting view and the database are separate spreadsheets. The client can never accidentally break the data — and they never have to request a report.","sidebar":false,"prev":false,"next":false},"headers":[],"relativePath":"blog/17-two-spreadsheets.md","filePath":"blog/17-two-spreadsheets.md","blogPosts":[{"url":"/blog/23-confidently-wrong","fm":{"title":"Confidently Wrong","date":"2026-05-28","series":"AI Behaviour","description":"The most dangerous answer a system can give isn't \\\\\\"I don't know\\\\\\" — it's a confident answer about a world that has already changed. We spent a week teaching VERA the difference between what it remembers and what's true."}},{"url":"/blog/22-getvera-site","fm":{"title":"A Proper Address","date":"2026-04-18","series":"Infrastructure","description":"VERA now lives at getvera.site. The old GitHub Pages URL redirects automatically — but the address a prospect reads on a pricing page is part of the pitch."}},{"url":"/blog/21-not-everyone-works-forty-hours","fm":{"title":"Not Everyone Works Forty Hours","date":"2026-03-29","series":"Features","description":"Capacity planning only works if the system knows how each person actually works. VERA was treating your contractors like full-time employees. It no longer does."}},{"url":"/blog/20-when-done-means-done","fm":{"title":"When Done Means Done","date":"2026-03-25","series":"AI Behaviour","description":"A confirmation that nothing happened behind it is worse than no confirmation at all. We fixed the moment where trust breaks."}},{"url":"/blog/19-the-briefing","fm":{"title":"The Briefing That Replaced the Monday Check-in","date":"2026-03-24","series":"Features","description":"The morning summary now answers two questions simultaneously: what am I supposed to be working on, and where do my projects stand?"}},{"url":"/blog/18-sheets-formulas-as-code","fm":{"title":"Building the Dashboard the Owner Actually Needs","date":"2026-03-15","series":"Data Model","description":"A live dashboard that answers the real questions: which projects are healthy, which are at risk, and what the business earned this month."}},{"url":"/blog/17-two-spreadsheets","fm":{"title":"The Dashboard Is Always Current","date":"2026-03-13","series":"Architecture","description":"The client''s reporting view and the database are separate spreadsheets. The client can never accidentally break the data — and they never have to request a report."}},{"url":"/blog/16-column-order-is-the-api","fm":{"title":"The Invisible Contract in the Spreadsheet","date":"2026-03-12","series":"Data Model","description":"Google Sheets doesn''t enforce its own structure. We had to. The rules we built to keep the data trustworthy."}},{"url":"/blog/14-agile-as-billing-model","fm":{"title":"Agile as a Billing Model","date":"2026-03-08","series":"Business Logic","description":"A sprint is a delivery unit and a revenue recognition unit. Timeliness of logging determines timeliness of revenue — they''re the same thing."}},{"url":"/blog/15-ooo-is-a-financial-event","fm":{"title":"Absence Is Data Too","date":"2026-03-08","series":"Business Logic","description":"Time off is a cost. If it doesn''t appear in the same system as time worked, the capacity picture is wrong and the P&L is incomplete."}},{"url":"/blog/13-design-md-rethink","fm":{"title":"Writing It Down Made Us Confront What We''d Built","date":"2026-03-07","series":"Architecture","description":"Six weeks in, we stopped and wrote down every decision we''d made. Several of them turned out to be wrong."}},{"url":"/blog/12-phased-expansion","fm":{"title":"What Becomes Possible When the Data Is Real","date":"2026-03-03","series":"Features","description":"Once time tracking is accurate and timely, a layer of project intelligence that was previously impossible becomes straightforward."}},{"url":"/blog/11-multi-tenancy-bugs","fm":{"title":"Reliability Is the Promise","date":"2026-03-01","series":"Architecture","description":"Timeliness only works if the system is there when the moment arrives. Getting multi-tenant reliability right was non-negotiable."}},{"url":"/blog/10-multi-tenancy","fm":{"title":"Each Client Gets Their Own VERA","date":"2026-02-25","series":"Architecture","description":"Multi-tenancy wasn''t a feature request. It was the point. A tool that feels shared feels like someone else''s."}},{"url":"/blog/09-timebot-becomes-vera","fm":{"title":"TimeBot Becomes VERA","date":"2026-02-22","series":"Origins","description":"A name signals a relationship. We weren''t building a utility."}},{"url":"/blog/07-retainers-are-weird","fm":{"title":"Retainers Without Timely Data Are Just Guesses","date":"2026-02-19","series":"Business Logic","description":"A retainer is a commitment to deliver a volume of work within a period. If you don''t know where you are until the invoice, you''ve already lost."}},{"url":"/blog/08-snapshots-version-control-spreadsheet","fm":{"title":"The Business Was There Last Tuesday Too","date":"2026-02-19","series":"Infrastructure","description":"When data is live and timely, the next question is whether you can go back. We built that in from the start."}},{"url":"/blog/06-roles-and-dollars","fm":{"title":"The Data Is Only Worth Protecting If It''s Worth Something","date":"2026-02-17","series":"Permissions","description":"When the data is timely and accurate, the financial numbers become real. Real numbers need to reach the right people — and not the wrong ones."}},{"url":"/blog/04-schema-grows-up","fm":{"title":"Making a Slack Message Do the Work of a Form","date":"2026-02-12","series":"Data Model","description":"We removed the interface. That meant every piece of information the owner needed had to be captured from a casual Slack message without making that message any harder to send."}},{"url":"/blog/05-prompt-engineering-wars","fm":{"title":"The Clarifying Questions Problem","date":"2026-02-12","series":"AI Behaviour","description":"Timeliness is the whole product. Any friction that risks the timing is a product failure."}},{"url":"/blog/03-socket-mode-railway","fm":{"title":"The Deployment That Didn''t Require a Web App","date":"2026-02-11","series":"Infrastructure","description":"We needed to deploy without adding anything to the client''s stack. Socket Mode and Railway made that possible for almost nothing."}},{"url":"/blog/01-the-problem","fm":{"title":"The Problem That Made VERA Necessary","date":"2026-02-10","series":"Origins","description":"Every time tracking tool ever built starts from the wrong assumption. We found the one thing that fixes it."}},{"url":"/blog/02-day-one-slack-claude-sheets","fm":{"title":"Day One: Slack → Claude → Google Sheets","date":"2026-02-10","series":"Origins","description":"The three components we chose on day one — and why each one was chosen specifically because it required no new interface."}}]}`),r={name:"blog/17-two-spreadsheets.md"};function n(o,t,l,h,d,c){return a(),i("div",null,[...t[0]||(t[0]=[e("p",null,"There's a version of reporting that most agencies still run: someone assembles a deck or a spreadsheet at the end of the month, pulls numbers from various systems, formats it, and sends it to the client or the owner. It takes time, it introduces the possibility of error, and it's a snapshot of a moment that has already passed by the time anyone reads it.",-1),e("p",null,"We built VERA to make that process unnecessary.",-1),e("p",null,"Every client has two spreadsheets. The first is the database — where VERA reads and writes, where the time entries live, where the project and budget data is stored. The client never touches this sheet. The service account that VERA uses to access Google Sheets has editor access. The client doesn't need any access at all.",-1),e("p",null,"The second spreadsheet is the reporting view. This is the one the client — or the owner, or the finance person — actually looks at. It's structured the way they want it. It has the tabs that make sense for their business. And it pulls its data live from the database sheet using Google's IMPORTRANGE function.",-1),e("hr",null,null,-1),e("p",null,"Because the reporting sheet references the database sheet directly, it's always current. The moment a time entry is logged in Slack, it appears in the database. The moment it appears in the database, it's visible in the reporting sheet. No export, no assembly, no request. The dashboard is live.",-1),e("p",null,"The separation also means the two sheets can evolve independently. The client can restructure their reporting view — add a tab, change the layout, rename a column for their audience — without touching the database. And we can update the database schema when the product requires it, without disrupting what the client sees.",-1),e("p",null,`This is what "no new interface" looks like for the output side. The owner doesn't visit a product dashboard. They open a Google Sheet they already know, and it tells them what's happening in their business right now.`,-1)])])}const p=s(r,[["render",n]]);export{m as __pageData,p as default};
